<?php

namespace Jurager\Teams\Database\Factories;

use Illuminate\Database\Eloquent\Factories\Factory;
use Illuminate\Database\Eloquent\Model;
use Illuminate\Support\Facades\Config;
use Jurager\Teams\Support\Facades\Teams;

class GroupFactory extends Factory
{
    /**
     * Get the name of the model that is generated by the factory.
     */
    public function modelName(): string
    {
        return Teams::model('group');
    }

    /**
     * Define the model's default state.
     *
     * @return array<string, mixed>
     */
    public function definition(): array
    {
        return [
            Config::get('teams.foreign_keys.team_id') => Teams::model('team')::factory(),
            'code' => fake()->unique()->slug(2),
        ];
    }

    /**
     * Make the group global, without a team.
     */
    public function global(): static
    {
        return $this->state([Config::get('teams.foreign_keys.team_id') => null]);
    }

    /**
     * Grant the given permissions to the group.
     */
    public function grant(string ...$codes): static
    {
        return $this->afterCreating(fn (Model $group) => $group->grant($codes));
    }
}
